log(`Judging ${TASKS.length} weakness/concern segments from ReviewCritique_LLM.jsonl`)

function buildPrompt(t) {
  return `You are an expert NLP/ML conference meta-reviewer. Judge whether ONE specific weakness/concern segment from a review is reliable, USING THE PAPER TEXT as ground truth.

Error type table:
${ERROR_TYPE_TABLE}

Weakness reliability guideline (error type table + human-annotated examples):
${GUIDELINE}

First, use the Read tool to read the full paper text at: ${t.paper_path}
Then, use the Read tool to read the full review (for context) at: ${t.review_path}

The SPECIFIC segment to judge (this is the only segment you are scoring; the rest of the review is context only):
=== SEGMENT START ===
${t.segment_text}
=== SEGMENT END ===

Task:
Judge whether THIS SPECIFIC segment is reliable BY CHECKING IT AGAINST THE PAPER TEXT.

Return:
- reliable: 1 if this segment is genuinely supported by the paper (the flaw really exists, the omission is real, the critique is well-grounded). 0 if it matches one of the error patterns in the guideline (Misunderstanding/Neglect/etc.).
- error_type: if reliable=0, choose the single best-matching label from the error type table (exact label text). If reliable=1, use an empty string.
- justification: 1-2 sentences citing the specific paper passage.

Be strict. If the segment's claim contradicts something explicitly in the paper, mark it Neglect/Misunderstanding. If you cannot find supporting evidence in the paper for what the segment claims is missing, double-check the paper before marking reliable=1.

Return your result via the required structured output only.`
}

const CONCURRENCY = 5
const results = []
for (let i = 0; i < TASKS.length; i += CONCURRENCY) {
  const chunk = TASKS.slice(i, i + CONCURRENCY)
  const chunkResults = await parallel(chunk.map((t) => async () => {
    const out = await agent(buildPrompt(t), {
      label: `p${t.paper_idx}_${t.reviewer}_s${t.seg_idx}`,
      schema: SCHEMA,
      model: 'sonnet',
    })
    if (!out) return null
    return {
      paper_idx: t.paper_idx,
      reviewer: t.reviewer,
      seg_idx: t.seg_idx,
      segment_text: t.segment_text,
      ground_truth_reliability: t.ground_truth_reliability,
      ground_truth_error_type: t.ground_truth_error_type,
      pred_reliable: out.reliable,
      pred_error_type: out.error_type,
      pred_justification: out.justification,
    }
  }))
  results.push(...chunkResults)
  log(`chunk ${i / CONCURRENCY + 1}/${Math.ceil(TASKS.length / CONCURRENCY)} done`)
}

const flat = results.filter(Boolean)
log(`${flat.length} segments scored`)
return flat
